// Aurora 2D — slow green curtains with a violet shimmer
export var band = 0
export var shimmerAmp = 0
var cellSize = 1, speed = .4, ph = .33, sparkle = 1, t1 = 0
export function sliderCellSize(v) { cellSize = v }  //# min=.2 max=4 default=1
export function sliderSpeed(v) { speed = v }  //# min=0 max=1 default=.4
export function hsvPickerPalette(h, s, v) { ph = h }  //# default=.33
export function toggleSparkle(v) { sparkle = v }  //# default=1
export function beforeRender(delta) {
  t1 = time(.1 * speed)
  band = wave(t1) * .35 + .5
  shimmerAmp = .12 + band * .08
}
export function render2D(index, x, y) {
  var curtain = clamp(1 - abs(y - band) * 3.2 * cellSize, 0, 1)
  var v = clamp(curtain * (.55 + shimmerAmp * sparkle), 0, 1)
  hsv(ph - v * .06, 1 - v * .35, v * v)
}

export function sliderSpeed(v) {
  speed = v
}
var speed = .1
export function render2D(index, x, y) {
  var v = wave(y + time(speed))
  hsv(.58, .7, v * v)
}

export function render(index) {
  var f = index / pixelCount
  hsv(.08 - f * .06, 1, 1 - f * .3)
}

export function render(index) {
  var f = index / pixelCount
  hsv(.6, 1, wave(f + time(.05)))
}

export function render(index) {
  var f = index / pixelCount
  hsv(.04, 1, 1 - f)
}

